//! 🪢️ Original allocation callback boundaries retain actual backing and recorded recipient verdicts.
use super::super::{NativeAllocationRequest as Request,NativeAllocationEvent as Event,NativeDecodeAllocationPhase as Phase};
use crate::native_decoding::NativeDecodeControl;
use crate::{ValueError,ValueRefusalKind,RetainedCloneGrant};
use std::sync::{Mutex,atomic::{AtomicUsize,Ordering}};
#[derive(Default)]struct Receiver{pending:Mutex<Option<Request>>,submitted:AtomicUsize,verdict:Mutex<Option<Result<(),crate::NativeAllocationRefusal>>>}
impl Receiver{fn accept(&self,event:Event,target:&str)->Result<(),crate::NativeAllocationRefusal>{let name=match event{Event::Admit(_)=>"admit",Event::Quote(request)=>{assert!(self.pending.lock().unwrap().replace(request).is_none());"quote"},Event::Post{request,actual}=>{assert_eq!(self.pending.lock().unwrap().take(),Some(request));self.submitted.fetch_add(actual,Ordering::Relaxed);"post"},Event::Cancel(request)=>{assert_eq!(self.pending.lock().unwrap().take(),Some(request));"cancel"}};if name==target{*self.verdict.lock().unwrap()=Some(Ok(()));panic!("original recipient interrupted after recording its verdict")}Ok(())}fn take_verdict(&self)->Result<(),crate::NativeAllocationRefusal>{self.verdict.lock().unwrap().take().expect("original recipient recorded its verdict")}}
fn birth(bytes:usize,output:&mut Option<Vec<u8>>,actual:&mut Option<usize>)->Result<(),ValueError>{let layout=std::alloc::Layout::array::<u8>(bytes).map_err(|_|ValueError::literal(ValueRefusalKind::OwnershipLimit,"fixture layout"))?;let pointer=unsafe{std::alloc::alloc(layout)};if pointer.is_null(){*actual=Some(0);return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation"))}*output=Some(unsafe{Vec::from_raw_parts(pointer,0,bytes)});*actual=Some(bytes);Ok(())}
fn close<T:crate::retirement::RetireOwned>(value:T){let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).ok().unwrap();while !owner.terminal_is_empty(){owner.step(grant).unwrap();}}
#[test]fn original_port_panic_retains_actual_verdict_and_backing(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🛫️encode/🛂️allocation/🧪️tests/🧫️fixtures/🪢️port-unwind/🔣️.json")).unwrap();let bytes=fixture["bytes"].as_u64().unwrap()as usize;for case in fixture["cases"].as_array().unwrap().iter().filter(|row|row["port"]=="forwarded"){let selected=case["port"].as_str().unwrap();let target=case["event"].as_str().unwrap();let forwarded=Receiver::default();let mut forwarded_port=|event|forwarded.accept(event,if selected=="forwarded"{target}else{""});let mut callback=|_|true;let mut forwarded_issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut forwarded_loan=forwarded_issuer.loan(&mut forwarded_port);let mut control=NativeDecodeControl::new_forwarded(bytes,&mut callback,&mut forwarded_loan);let mut actual=None;let mut retained=None;let mut output=None;let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.allocate_effect(bytes,&mut actual,&mut retained,&mut |actual|{if target=="cancel"{Err(ValueError::literal(ValueRefusalKind::Canceled,"fixture allocation failed"))}else{birth(bytes,&mut output,actual)}})));assert!(result.is_err());let state=retained.as_mut().unwrap();assert_eq!(state.request.bytes,bytes);assert_eq!(state.outcome.request,Some(state.request));assert_eq!(state.outcome.actual,case["actual"].as_u64().map(|v|v as usize));assert_eq!(state.phase,if target=="quote"{Phase::QuoteStarted}else{Phase::SettlementStarted});assert!(crate::retirement::RetireOwned::retirement_birth_bytes(state).is_none());assert!(control.settle_allocation_progress(state,actual).is_err());let verdict=forwarded.take_verdict();control.resolve_allocation_callback(state,verdict).unwrap();control.settle_allocation_progress(state,actual).unwrap();let state=retained.take().unwrap();drop(control);assert!(forwarded.pending.lock().unwrap().is_none());assert_eq!(forwarded.submitted.load(Ordering::Relaxed),if target=="post"{bytes}else{0});close(state);if let Some(output)=output.take(){close(output)}}}
#[test]fn operation_unwind_settles_real_backing_through_original_port(){let receiver=Receiver::default();let mut port=|event|receiver.accept(event,"");let mut callback=|_|true;let mut allocation_loan_issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.loan(&mut port);let mut control=NativeDecodeControl::new_forwarded(8,&mut callback,&mut allocation_loan);let mut actual=None;let mut retained=None;let mut output=None;let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.allocate_effect(8,&mut actual,&mut retained,&mut |actual|{birth(8,&mut output,actual)?;panic!("operation interrupted after real allocation")})));assert!(result.is_err());let state=retained.as_mut().unwrap();assert_eq!(state.outcome.actual,Some(8));assert_eq!(state.phase,Phase::QuoteAccepted);control.settle_allocation_progress(state,actual).unwrap();let state=retained.take().unwrap();drop(control);assert_eq!(receiver.submitted.load(Ordering::Relaxed),8);assert!(receiver.pending.lock().unwrap().is_none());close(state);close(output.take().unwrap());}

#[test]
fn partial_actual_refusal_reports_the_committed_extent(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🛫️encode/🛂️allocation/🧪️tests/🧫️fixtures/🪢️port-unwind/🔣️.json")).unwrap();let request=fixture["partial"]["requestBytes"].as_u64().unwrap() as usize;let actual_bytes=fixture["partial"]["actualBytes"].as_u64().unwrap() as usize;
 let mut port=|event:Event|match event{Event::Post{..}=>Err(ValueError::literal(ValueRefusalKind::Canceled,"actual post refused").into()),_=>Ok(())};let mut issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=issuer.loan(&mut port);let mut observer=|_|true;let mut native=NativeDecodeControl::new_forwarded(request,&mut observer,&mut loan);let mut output=None;let mut actual=None;let mut progress=None;let outcome=native.allocate_effect(request,&mut actual,&mut progress,&mut |actual|birth(actual_bytes,&mut output,actual));assert_eq!(native.owned_bytes(),request);assert_eq!(outcome.actual,Some(actual_bytes));let failure=outcome.into_allocation_failure(0).unwrap();assert_eq!(failure.progress.admitted_bytes,request);assert_eq!(failure.progress.requested_bytes,Some(request));assert_eq!(failure.progress.actual_capacity_bytes,Some(actual_bytes));assert!(failure.forwarded_post.is_some());assert!(progress.is_none());drop(native);close(failure);close(output.take().unwrap());
}

#[test]
fn forwarded_frame_retains_owned_output_and_pending_original_work(){
 use crate::native_decoding::{NativeForwardedDecodeFrame,NativeDecodeRetirementRecipient,NativeDecodeAllocationIssuer,OriginalWorkActionIssuer,OriginalWorkRecipient,OriginalWorkQuote,OriginalWorkQuoteComplete};
 struct Work;impl OriginalWorkRecipient for Work{fn admits<'a>(&mut self,quote:OriginalWorkQuote<'a>,_:u64,_:u64)->OriginalWorkQuoteComplete<'a>{quote.complete((||{Ok(true)})())}}
 let mut recipient=NativeDecodeRetirementRecipient::new();let mut receipt=None;let mut allocation=|_:Event|Ok(());let mut issuer=NativeDecodeAllocationIssuer::new();let mut observer=|_|true;let mut work_issuer=OriginalWorkActionIssuer::new();let mut work=Work;let mut work_loan=work_issuer.loan(&mut work);
 let output=Box::new(73u64);let pointer=std::ptr::from_ref(output.as_ref());
 let failure={let mut allocation_loan=issuer.loan(&mut allocation);let mut frame=NativeForwardedDecodeFrame::begin(&mut receipt,128,&mut observer,&mut allocation_loan,&mut recipient).unwrap();
 let answer=frame.scope(|control|control.with_work_recipient(&mut work_loan,|control|{assert!(control.prepare_work(1)?);control.depth=1;Ok::<_,ValueError>(output)}));
 let failure=answer.unwrap_err();assert_eq!(std::ptr::from_ref(failure.output.as_ref().unwrap().as_ref()),pointer);assert!(failure.operation.is_none());assert!(failure.context.is_some());assert!(failure.receipt_refusal.is_none());
 drop(frame);failure};assert!(receipt.as_ref().unwrap().has_pending_work());
 {let mut allocation_loan=issuer.loan(&mut allocation);let mut frame=NativeForwardedDecodeFrame::begin(&mut receipt,128,&mut observer,&mut allocation_loan,&mut recipient).unwrap();
 frame.scope(|control|control.with_work_recipient(&mut work_loan,|control|control.cancel_work())).unwrap();drop(frame);}
 assert!(!receipt.as_ref().unwrap().has_pending_work());drop(failure);
}

#[test]
fn forwarded_frame_unwind_returns_the_original_admission_receipt(){
 use crate::native_decoding::{NativeForwardedDecodeFrame,NativeDecodeRetirementRecipient,NativeDecodeAllocationIssuer};
 let receiver=Receiver::default();let mut port=|event|receiver.accept(event,"");
 let mut issuer=NativeDecodeAllocationIssuer::new();let mut observer=|_|true;let mut recipient=NativeDecodeRetirementRecipient::new();let mut receipt=None;
 let mut output=None;let mut actual=None;let mut allocation=None;
 let outcome=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{
  let mut loan=issuer.loan(&mut port);let mut frame=NativeForwardedDecodeFrame::begin(&mut receipt,8,&mut observer,&mut loan,&mut recipient).unwrap();
  let _:Result<(),crate::native_decoding::NativeCallFailure<(),ValueError>>=frame.scope(|control|{
   let outcome=control.allocate_effect(8,&mut actual,&mut allocation,&mut |actual|birth(8,&mut output,actual));
   assert!(outcome.primary.is_none());panic!("original allocated output remains in its caller slot");
  });
 }));
 assert!(outcome.is_err());assert_eq!(receipt.as_ref().unwrap().owned_bytes(),8);assert!(receiver.pending.lock().unwrap().is_none());assert_eq!(receiver.submitted.load(Ordering::Relaxed),8);assert_eq!(actual,Some(8));close(output.take().unwrap());
}
